/**
 * Font tambahan yang DISEMATKAN (base64, bukan tautan CDN Google Fonts) — supaya hasil ekspor
 * (ZIP/HTML mandiri) tetap bisa dibuka 100% offline, konsisten dengan prinsip desain aplikasi ini
 * (lihat README: "Tanpa jaringan/CDN/server"). Hanya subset Latin (cukup untuk Indonesia/Inggris)
 * dan hanya bobot yang benar-benar dipakai, supaya ukurannya tetap kecil (~100 KB total).
 *
 * Satu sumber (string CSS ini) dipakai DUA tempat: disuntikkan sebagai <style> di aplikasi utama
 * (lihat pemanggilan di main.tsx) dan disisipkan langsung ke RUNTIME_CSS hasil ekspor
 * (services/export/runtimeCss.ts) — supaya pratinjau Studio & hasil ekspor terlihat identik.
 */

export const EMBEDDED_FONTS_CSS = `
@font-face { font-family: 'Space Grotesk'; font-style: normal; font-weight: 400 700; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }
@font-face { font-family: 'Poppins'; font-style: normal; font-weight: 400; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }
@font-face { font-family: 'Poppins'; font-style: normal; font-weight: 700; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }
@font-face { font-family: 'Playfair Display'; font-style: normal; font-weight: 700; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }
@font-face { font-family: 'Bebas Neue'; font-style: normal; font-weight: 400; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }
`;

/** Suntikkan sekali di aplikasi utama (bukan hasil ekspor, yang menyisipkannya langsung ke RUNTIME_CSS). */
export function injectEmbeddedFonts(): void {
  if (typeof document === 'undefined' || document.getElementById('embedded-fonts')) return;
  const style = document.createElement('style');
  style.id = 'embedded-fonts';
  style.textContent = EMBEDDED_FONTS_CSS;
  document.head.appendChild(style);
}
